draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw an apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw a stick figure eating the apple
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 80, H/2 + 60); // leg
  ctx.stroke();

  // animate the stick figure eating the apple
  ctx.beginPath();
  ctx.arc(W/2 - 100 + Math.sin(t) * 10, H/2 - 50, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + Math.sin(t) * 10, H/2 - 30);
  ctx.lineTo(W/2 - 100 + Math.sin(t) * 10, H/2 + 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + Math.sin(t) * 10, H/2 - 10);
  ctx.lineTo(W/2 - 120 + Math.sin(t) * 10, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + Math.sin(t) * 10, H/2 + 30);
  ctx.lineTo(W/2 - 80 + Math.sin(t) * 10, H/2 + 60); // leg
  ctx.stroke();

  ctx.restore();
}
